//! Read-only persistent fixture routes for the one loopback mock.
//!
//! The HYP/Sophon/CDN world is generated by [`crate::World`]; the persistent
//! side is different. Its envelope, key, three manifests and hotfix blobs are
//! **committed offline inputs**: this module opens them from
//! `tests/fixtures/persistent_inputs/samples/fixtures/` and never edits or
//! regenerates them. The only bytes constructed here are the Collapse metadata
//! that *addresses* the dispatcher (a synthetic RSA-1024 master wrapped in the
//! same magic-blob format, a stamp table and a per-biz preset) and, for the
//! rotated profile, a fresh synthetic dispatcher key plus an envelope re-encrypted
//! from the committed plaintext. No production key or endpoint is involved.
//!
//! The route table is keyed by the **absolute URL** the real producer asks for,
//! because the metadata and dispatcher hosts are fixed by the product leaf and
//! cannot be rewritten with a CLI flag. The mock's transport recognises those
//! URLs before it falls back to the loopback-relative HYP/Sophon/CDN routes, so
//! one `Mock` answers every request the producer makes. The response body for
//! `query_cur_region` is the byte-exact fixture: the producer still fetches and
//! decodes it through the real `query_with_context` path.

use std::collections::BTreeMap;
use std::path::Path;

use base64::Engine as _;
use base64::engine::general_purpose::STANDARD;
use girpr_digest::decode_hex;
use girpr_dispatch::{
    DispatchDecodeParams, METADATA_BASE, ManifestKind, channel_prefix, decode_base64,
    decode_dispatch_response, decrypt_pkcs1_blocks, dispatch_host, dispatch_info_from_decoded,
    private_key_from_bytes, query_version, template_for,
};
use girpr_model::Region;
use girpr_persistent_plan::{asset_urls, folder_for, parse_rows};
use rsa::{
    PrivateKey, pkcs1::DecodeRsaPrivateKey, pkcs1v15::Pkcs1v15Encrypt, traits::PrivateKeyParts,
    traits::PublicKeyParts,
};
use serde_json::{Value, json};

/// The one dispatcher query version the committed envelope answers.
pub const LATEST: &str = "9.9.0";

/// The synthetic dispatcher seed in `fixtures.json`; pin is off in this mock.
const FIXTURE_SEED: &str = "0011223344556677";

/// A different seed for the rotated key, so the recorded `dispatch_url` moves too.
const ROTATED_SEED: &str = "7766554433221100";

/// `99000000 001122334455`, the second GET's body (C3's synthetic value).
const BASE_REVISION: &str = "99000000 001122334455";

/// Synthetic RSA-1024 PKCS#1 DER master, generated once for girpr's dispatcher
/// unit tests. It is not a release-repo key and `pin = false` skips the live
/// digest check that belongs to that key. Kept as bytes here so the mock owns
/// its own metadata builder and borrows no body from the repair binary.
const SYNTHETIC_MASTER_DER_HEX: &str = "";

/// Which dispatch key/seed the mock serves.
///
/// Both profiles decrypt to the same committed envelope plaintext, so every
/// manifest URL, revision and descriptor is identical; only the key material,
/// its fingerprint, the ciphertext bytes and the `dispatchSeed` in the query
/// URL change. That is what makes the key-rotation assertion meaningful: the
/// second bundle must verify from *its own* key and envelope.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DispatchProfile {
    /// The committed synthetic test key (`test_key.pem`) and its recorded seed.
    Fixture,
    /// A freshly generated synthetic key, a different seed and an envelope
    /// re-encrypted from the committed plaintext.
    Rotated,
}

/// Every absolute-URL route the persistent half of the capture asks for.
#[derive(Debug, Clone)]
pub struct PersistentRoutes {
    /// Absolute URL → byte-exact response body.
    bodies: BTreeMap<String, Vec<u8>>,
    key_material: Vec<u8>,
    seed: String,
    dispatch_url: String,
    envelope: Vec<u8>,
}

impl PersistentRoutes {
    /// The body served for `url`, when this mock owns that absolute URL.
    pub fn body(&self, url: &str) -> Option<&[u8]> {
        self.bodies.get(url).map(Vec::as_slice)
    }

    /// The private key material served in the per-biz preset (XML, test only).
    pub fn key_material(&self) -> &[u8] {
        &self.key_material
    }

    /// The seed served in the per-biz preset and used in the dispatcher URL.
    pub fn seed(&self) -> &str {
        &self.seed
    }

    /// The full `query_cur_region` URL the producer is expected to request.
    pub fn dispatch_url(&self) -> &str {
        &self.dispatch_url
    }

    /// The byte-exact dispatcher envelope served at `dispatch_url`.
    pub fn envelope(&self) -> &[u8] {
        &self.envelope
    }
}

/// Read one committed offline input, byte for byte. No regeneration, no writes.
pub fn fixture(name: &str) -> Vec<u8> {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../../tests/fixtures/persistent_inputs/samples/fixtures")
        .join(name);
    std::fs::read(&path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()))
}

/// Build every persistent route for `profile`.
///
/// The absolute URLs are derived from the committed plaintext with the same
/// pure helpers the producer uses, so a change to the URL rule cannot leave the
/// mock answering an address the producer no longer requests.
pub fn routes(profile: DispatchProfile) -> PersistentRoutes {
    let biz = Region::Hk4eGlobal;
    let fixture_envelope = fixture("dispatch_response.json");
    let fixture_key = private_key_from_bytes(&fixture("test_key.pem"))
        .expect("the committed synthetic dispatcher key parses");

    // Decrypt the committed envelope once. The rotated profile re-encrypts this
    // plaintext with a fresh synthetic key; nothing in the decoded facts changes.
    let value: Value = serde_json::from_slice(&fixture_envelope).expect("envelope JSON");
    let content = value["content"].as_str().expect("envelope content");
    let plaintext =
        decrypt_pkcs1_blocks(&fixture_key, &decode_base64(content).expect("base64"), 256)
            .expect("the committed envelope decrypts");

    let (key, seed, envelope, key_material) = match profile {
        DispatchProfile::Fixture => {
            // Keep the `dispatch/key.pem` filename historical: the bytes C3
            // writes there are RSAKeyValue XML, which girpr also accepts.
            let xml = key_xml(&fixture_key).into_bytes();
            (fixture_key, FIXTURE_SEED.to_string(), fixture_envelope, xml)
        }
        DispatchProfile::Rotated => {
            let rotated = PrivateKey::new(&mut rand::rng(), 2048).expect("generate a test key");
            let ciphertext = encrypt_blocks(&rotated, &plaintext);
            let envelope = format!(
                "{{\"content\":\"{}\",\"sign\":\"{}\"}}",
                STANDARD.encode(ciphertext),
                STANDARD.encode([0u8; 256])
            )
            .into_bytes();
            let key_material = key_xml(&rotated).into_bytes();
            (rotated, ROTATED_SEED.to_string(), envelope, key_material)
        }
    };

    let decoded = decode_dispatch_response(
        &envelope,
        DispatchDecodeParams {
            biz,
            latest: LATEST,
            host: dispatch_host(biz),
            channel_prefix: channel_prefix(biz),
            exe_stem: "GenshinImpact",
            key: &key,
            block_bytes: 256,
        },
    )
    .expect("the served envelope decodes");

    let master = PrivateKey::from_pkcs1_der(&decode_hex(SYNTHETIC_MASTER_DER_HEX).expect("hex"))
        .expect("the synthetic master key parses");
    let config_file = "config_GIGlb.json";
    let dispatch_url = girpr_dispatch::build_dispatcher_url(
        template_for(biz),
        dispatch_host(biz),
        &query_version(biz, LATEST),
        &seed,
    )
    .expect("build the dispatcher URL");
    girpr_dispatch::validate_dispatcher_url(&dispatch_url, biz)
        .expect("the served template validates");

    let mut bodies = BTreeMap::new();
    bodies.insert(master_url(), master_json(&master));
    bodies.insert(
        format!("{METADATA_BASE}/stamp.json"),
        stamp_json(config_file),
    );
    bodies.insert(
        format!("{METADATA_BASE}/{config_file}"),
        config_json(&master, &key_material, &seed),
    );
    bodies.insert(dispatch_url.clone(), envelope.clone());

    let info = dispatch_info_from_decoded(decoded.clone(), BASE_REVISION)
        .expect("the served base_revision decodes");
    bodies.insert(
        decoded.base_revision_url.clone(),
        BASE_REVISION.as_bytes().to_vec(),
    );

    for (kind, file) in [
        (ManifestKind::Res, "res.ndjson"),
        (ManifestKind::Data, "data.ndjson"),
        (ManifestKind::Silence, "silence.ndjson"),
    ] {
        let url = info
            .manifest_digests
            .iter()
            .find(|d| d.kind == kind)
            .expect("a descriptor for every manifest kind")
            .url
            .clone();
        bodies.insert(url, fixture(file));
    }
    let a = fixture("hotfix_a.blk");
    let b = fixture("hotfix_b.pck");
    let by_md5 = |md5: &str| -> Vec<u8> {
        if gircap::hash::md5_hex(&a).eq_ignore_ascii_case(md5) {
            a.clone()
        } else if gircap::hash::md5_hex(&b).eq_ignore_ascii_case(md5) {
            b.clone()
        } else {
            panic!("no committed fixture bytes for md5 {md5}")
        }
    };
    for (kind, file) in [
        (ManifestKind::Res, "res.ndjson"),
        (ManifestKind::Data, "data.ndjson"),
        (ManifestKind::Silence, "silence.ndjson"),
    ] {
        for row in parse_rows(&fixture(file)).expect("a committed manifest parses") {
            let (url, _) = asset_urls(
                &info,
                kind,
                folder_for(&row.remote_name),
                &row.remote_name,
                false,
            )
            .expect("a CDN URL for a committed row");
            bodies.insert(url, by_md5(&row.md5));
        }
    }

    PersistentRoutes {
        bodies,
        key_material,
        seed,
        dispatch_url,
        envelope,
    }
}

/// The fixed metadata root, spelled from the product leaf rather than copied.
fn master_url() -> String {
    format!("{METADATA_BASE}/config_master.json")
}

/// DataCooker's `Collapse` magic signature, as the little-endian i64 the header
/// parser expects.
const MAGIC_SIGNATURE: i64 = 7310310183885631299;
const HEADER_LEN: usize = 32;

fn magic(flags: i64, payload: Vec<u8>, decompressed_size: usize) -> Vec<u8> {
    let mut raw = Vec::with_capacity(HEADER_LEN + payload.len());
    raw.extend_from_slice(&MAGIC_SIGNATURE.to_le_bytes());
    raw.extend_from_slice(&flags.to_le_bytes());
    raw.extend_from_slice(&(payload.len() as i64).to_le_bytes());
    raw.extend_from_slice(&(decompressed_size as i64).to_le_bytes());
    raw.extend_from_slice(&payload);
    raw
}

fn compress(data: &[u8]) -> Vec<u8> {
    let mut writer = brotli::CompressorWriter::new(Vec::new(), 4096, 5, 22);
    std::io::Write::write_all(&mut writer, data).expect("brotli compress");
    writer.into_inner()
}

/// flags `0x1`: Brotli only — the master key's own blob.
fn wrap_plain(text: &[u8]) -> String {
    STANDARD.encode(magic(1, compress(text), text.len()))
}

/// flags `0x101`: Brotli + RSA in 128-byte master-key blocks.
fn wrap_encrypted(text: &[u8], master: &PrivateKey, block: usize) -> String {
    let compressed = compress(text);
    let mut ciphertext = Vec::new();
    for chunk in compressed.chunks(block - 11) {
        ciphertext.extend(
            master
                .to_public_key()
                .encrypt(&mut rand::rng(), Pkcs1v15Encrypt, chunk)
                .expect("master encrypt"),
        );
    }
    // The header records the *compressed* (post-RSA) size, not the ciphertext
    // size: `unwrap_magic_blob` checks it after decryption.
    let mut raw = Vec::with_capacity(HEADER_LEN + ciphertext.len());
    raw.extend_from_slice(&MAGIC_SIGNATURE.to_le_bytes());
    raw.extend_from_slice(&0x101i64.to_le_bytes());
    raw.extend_from_slice(&(compressed.len() as i64).to_le_bytes());
    raw.extend_from_slice(&(text.len() as i64).to_le_bytes());
    raw.extend_from_slice(&ciphertext);
    STANDARD.encode(raw)
}

fn master_json(master: &PrivateKey) -> Vec<u8> {
    use rsa::pkcs1::EncodeRsaPrivateKey as _;
    let der = master
        .to_pkcs1_der()
        .expect("master DER")
        .as_bytes()
        .to_vec();
    serde_json::to_vec(&json!({"Key": wrap_plain(&der), "BitSize": 128})).expect("master json")
}

fn stamp_json(config_file: &str) -> Vec<u8> {
    serde_json::to_vec(&json!([{
        "GameName": "Genshin Impact",
        "GameRegion": "Global",
        "MetadataType": "PresetConfigV2",
        "MetadataPath": config_file,
    }]))
    .expect("stamp json")
}

fn config_json(master: &PrivateKey, key: &[u8], seed: &str) -> Vec<u8> {
    serde_json::to_vec(&json!({
        "ProfileName": "GIGlb",
        // Plain strings are passed through `unwrap_metadata_field` unchanged;
        // only the dispatcher key needs the encrypted magic blob.
        "GameDispatchURL": template_for(Region::Hk4eGlobal),
        "ProtoDispatchKey": seed,
        "DispatcherKeyBitLength": 256,
        "DispatcherKey": wrap_encrypted(key, master, 128),
        "ChannelID": 1,
        "SubChannelID": 0,
        "GameExecutableName": "GenshinImpact.exe",
    }))
    .expect("config json")
}

/// .NET `RSAKeyValue` spelling accepted by girpr's key parser. Built from the
/// committed PEM (or the rotated key) so no second key file is committed.
fn key_xml(key: &PrivateKey) -> String {
    let part = |bytes: Vec<u8>| STANDARD.encode(bytes);
    let primes = key.primes();
    format!(
        "<RSAKeyValue><Modulus>{}</Modulus><Exponent>{}</Exponent><D>{}</D>\
         <P>{}</P><Q>{}</Q></RSAKeyValue>",
        part(key.n().to_be_bytes_trimmed_vartime().into_vec()),
        part(key.e().to_be_bytes_trimmed_vartime().into_vec()),
        part(key.d().to_be_bytes_trimmed_vartime().into_vec()),
        part(primes[0].to_be_bytes_trimmed_vartime().into_vec()),
        part(primes[1].to_be_bytes_trimmed_vartime().into_vec()),
    )
}

fn encrypt_blocks(key: &PrivateKey, plaintext: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    for chunk in plaintext.chunks(245) {
        out.extend(
            key.to_public_key()
                .encrypt(&mut rand::rng(), Pkcs1v15Encrypt, chunk)
                .expect("test envelope encrypt"),
        );
    }
    out
}
